import os
import sys
import ctypes
import subprocess

SO_PATH = os.path.join(os.path.dirname(os.path.abspath(__file__)), '_fastsort.so')

C_CODE = r"""
#include <stdint.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>

void run_sort(const unsigned char *in_buf, size_t in_len) {
    size_t max_n = (in_len >> 1) + 2;
    uint64_t *a = (uint64_t *)malloc(max_n * sizeof(uint64_t));
    uint64_t *b = (uint64_t *)malloc(max_n * sizeof(uint64_t));
    size_t n = 0;
    size_t i = 0;

    while (i < in_len) {
        while (i < in_len && in_buf[i] <= ' ') i++;
        if (i >= in_len) break;
        int neg = 0;
        if (in_buf[i] == '-') {
            neg = 1;
            i++;
        } else if (in_buf[i] == '+') {
            i++;
        }
        uint64_t val = 0;
        while (i < in_len && in_buf[i] >= '0' && in_buf[i] <= '9') {
            val = val * 10 + (uint64_t)(in_buf[i] - '0');
            i++;
        }
        int64_t sval = neg ? -(int64_t)val : (int64_t)val;
        a[n++] = ((uint64_t)sval) ^ 0x8000000000000000ULL;
    }

    size_t count[8][256];
    memset(count, 0, sizeof(count));
    for (size_t j = 0; j < n; j++) {
        uint64_t v = a[j];
        count[0][v & 0xFF]++;
        count[1][(v >> 8) & 0xFF]++;
        count[2][(v >> 16) & 0xFF]++;
        count[3][(v >> 24) & 0xFF]++;
        count[4][(v >> 32) & 0xFF]++;
        count[5][(v >> 40) & 0xFF]++;
        count[6][(v >> 48) & 0xFF]++;
        count[7][(v >> 56) & 0xFF]++;
    }

    uint64_t *src = a;
    uint64_t *dst = b;
    for (int p = 0; p < 8; p++) {
        int shift = p * 8;
        if (n > 0 && count[p][(src[0] >> shift) & 0xFF] == n) continue;
        size_t sum = 0;
        for (int c = 0; c < 256; c++) {
            size_t tmp = count[p][c];
            count[p][c] = sum;
            sum += tmp;
        }
        for (size_t j = 0; j < n; j++) {
            uint64_t v = src[j];
            dst[count[p][(v >> shift) & 0xFF]++] = v;
        }
        uint64_t *tmp_ptr = src;
        src = dst;
        dst = tmp_ptr;
    }

    char *out = (char *)malloc(in_len + n + 64);
    char *p = out;
    char tmp[24];
    for (size_t j = 0; j < n; j++) {
        int64_t x = (int64_t)(src[j] ^ 0x8000000000000000ULL);
        uint64_t u;
        if (x < 0) {
            *p++ = '-';
            u = (uint64_t)(-(x + 1)) + 1ULL;
        } else {
            u = (uint64_t)x;
        }
        int k = 0;
        do {
            tmp[k++] = (char)('0' + (u % 10));
            u /= 10;
        } while (u > 0);
        while (k > 0) *p++ = tmp[--k];
        *p++ = '\n';
    }

    size_t total = (size_t)(p - out);
    size_t written = 0;
    while (written < total) {
        ssize_t w = write(1, out + written, total - written);
        if (w <= 0) break;
        written += (size_t)w;
    }

    free(a);
    free(b);
    free(out);
}
"""

def main():
    if not os.path.exists(SO_PATH):
        c_path = SO_PATH + '.c'
        with open(c_path, 'w') as f:
            f.write(C_CODE)
        env = os.environ.copy()
        env['TMPDIR'] = os.path.dirname(SO_PATH)
        subprocess.run(['gcc', '-O3', '-shared', '-fPIC', c_path, '-o', SO_PATH], env=env, check=True)
        os.remove(c_path)
    lib = ctypes.CDLL(SO_PATH)
    lib.run_sort.argtypes = [ctypes.c_char_p, ctypes.c_size_t]
    lib.run_sort.restype = None
    data = sys.stdin.buffer.read()
    lib.run_sort(data, len(data))

if __name__ == '__main__':
    main()
